insert into public.journal_posts("slug","title","date","category","readingTime","excerpt","featuredImage","content",published) values
('nourishing-hope','Nourishing Hope with Education and Meals','May 18, 2026','Education','5 min read','How KCG Foundation connects school support and daily nutrition to create stable learning paths for children in Haryana.','https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=900&q=80','<p>KCG Foundation combines classroom support, uniforms, and books with a daily nutritious meal program to help children stay in school and thrive. This holistic approach reduces dropout rates and improves wellbeing across families.</p><h2>Why Education and Meals Belong Together</h2><p>When children are both well-fed and supported academically, they can focus on learning instead of hunger. Our meal program ensures that every child arrives ready to learn, while our scholarship support covers essential school supplies.</p><h2>Creating Lasting Community Impact</h2><p>The families we serve tell us the same thing again and again: reliable meals and school support create calm at home, reduce stress, and give children a real chance at opportunity.</p><h3>What this means for students:</h3><ul><li>Regular classroom attendance</li><li>Improved nutrition and energy</li><li>Better academic performance</li></ul><h2>How You Can Help</h2><p>Supporting this program means providing monthly meal kits, educational materials, and mentorship for underprivileged students. Every effort strengthens an entire community.</p>',true),
('health-and-dignity-camps','Health and Dignity Camps for Workers and Families','May 10, 2026','Welfare','4 min read','Discover how KCG Foundation''s health camps bring medical care, dignity supplies, and rehabilitation to hard-working families in rural Haryana.','/images/Health-camp.jpg','<p>Our community health camps provide medical evaluations, hygiene kits, and compassionate counseling to daily wage earners and their loved ones. These camps are designed to restore dignity and reduce the burden of untreated illness.</p><h2>Designing Camps Around Local Needs</h2><p>Each camp meets families where they are, offering free screenings, medication, and hygiene education. We work with local volunteers so care is trusted and accessible.</p><h3>Core services delivered:</h3><ul><li>General health checkups</li><li>Basic medicines &amp; treatment referrals</li><li>Soap, sanitary kits, and clean drinking water support</li></ul><h2>Beyond Treatment</h2><p>Our goal is not just one-time care. We also connect families with local health resources and teach simple hygiene habits that reduce illness over time.</p>',true),
('scholarships-for-brighter-futures','Scholarships for Brighter Futures in Rural Communities','May 2, 2026','Scholarship','6 min read','Read about the scholarship program that helps motivated children access tuition, supplies, and mentorship across Haryana.','https://images.unsplash.com/photo-1528909514045-2fa4ac7a08ba?w=900&q=80','<p>The KCG scholarship program is built to reward determination and remove financial barriers. Selected students receive support for school fees, uniforms, books, and mentorship throughout the academic year.</p><h2>Supporting Students End to End</h2><p>Beyond payments, our scholarship families receive tailored guidance, tracking attendance and academic progress, while ensuring students feel supported at home.</p><h3>Student success looks like:</h3><ul><li>Improved grades and confidence</li><li>Regular attendance even during lean months</li><li>Stronger family stability thanks to reduced costs</li></ul><h2>Our Vision for 2026</h2><p>We aim to grow the scholarship cohort this year, reaching more rural children so their dreams are backed by real resources and consistent care.</p>',true),
('restoring-sight-cataract-surgery','Restoring Sight Through Cataract Surgery Support','June 2026','Healthcare','3 min read','KCG Foundation recently supported a cataract operation, helping restore vision and improve quality of life for a beneficiary and their family.','/images/cataract-operation.jpg','<p>KCG Foundation recently facilitated a cataract surgery for a community member suffering from severe vision impairment. Access to timely medical treatment restored eyesight and enabled the beneficiary to regain independence in daily life.</p><h2>Why This Matters</h2><p>Vision loss affects not only an individual but also their family and livelihood. Through community healthcare support initiatives, KCG Foundation continues to assist vulnerable individuals in accessing essential medical care.</p><h2>Impact</h2><ul><li>Successful cataract surgery completed</li><li>Improved quality of life and independence</li><li>Reduced healthcare burden on the family</li></ul><p>This initiative reflects our commitment to dignity, healthcare access, and community welfare.</p>',true)
